(function () {
  var D = window.ESEANS_I18N || {};
  function has(l) { return l && D[l]; }
  var qlang = null;
  try { qlang = new URLSearchParams(location.search).get('lang'); } catch (e) {}
  var ls = null;
  try { ls = localStorage.getItem('eseans_lang'); } catch (e) {}
  var inj = window.__ESLANG;
  if (inj === '__ESEANS_LANG__') inj = null; // dev: worker enjekte etmedi
  var nav = (navigator.language || '').slice(0, 2).toLowerCase();
  var cand = [qlang, ls, inj, nav, 'es'];
  var lang = 'es';
  for (var i = 0; i < cand.length; i++) { if (has(cand[i])) { lang = cand[i]; break; } }
  var dict = D[lang] || D.es || {};

  function apply() {
    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      var k = el.getAttribute('data-i18n');
      if (dict[k] != null) el.textContent = dict[k];
    });
    document.querySelectorAll('[data-i18n-html]').forEach(function (el) {
      var k = el.getAttribute('data-i18n-html');
      if (dict[k] != null) el.innerHTML = dict[k];
    });
    // Booking demo: slot secim suffix'i + baslangic meta metni.
    window.__BK_SUFFIX__ = dict.bkSlotSuffix || '';
    var meta = document.querySelector('.bk-meta');
    var sel = document.querySelector('.slot.sel');
    if (meta && sel && dict.bkSlotSuffix) meta.textContent = sel.textContent + ' ' + dict.bkSlotSuffix;
    // <html lang/dir> + title.
    document.documentElement.lang = lang;
    document.documentElement.dir = (lang === 'ar') ? 'rtl' : 'ltr';
    if (dict.pageTitle) document.title = dict.pageTitle;
    // Cloak kaldir.
    document.documentElement.style.visibility = 'visible';
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', apply);
  } else {
    apply();
  }
})();
